typedef unsigned int u_int;
typedef unsigned char uint8;

struct nglTexture;
struct nglQuadVertex
{
	float X, Y;
	float U, V;
	u_int Color;
};
struct nglQuad
{
	nglQuadVertex Verts[4];
	float Z;
	u_int MapFlags;
	u_int BlendMode;
	u_int BlendModeConstant;
	nglTexture* Tex;
};

class color32
{
public:
	union
	{
		struct { uint8 b, g, r, a; } c;
		u_int i;
	};
	void set_alpha(uint8 arg) { c.a = arg; }
};

class TextString
{
	char data[64];
public:
	bool no_color;
	char align[3];
	color32 color;
	virtual void Draw();
};

class PanelQuad
{
public:
	virtual ~PanelQuad();
	virtual void Init(float, float, float, float, float, float, float, float,
	                  float, float, float, float, float, void *);
	virtual void TurnOn(bool);
	virtual void SetLayer(int);
	virtual void Rotate(float);
	virtual void Rotate(float, float, float);
	virtual void Update(float);
	virtual void Draw(int layer = 0, float alpha = -1.0f);
	void SetFade(const float amt);
	virtual void SetZ(const float);
	virtual void SetCenterPos(float, float);
};

void nglSetQuadColor(nglQuad *, u_int);
void nglSetQuadBlend(nglQuad *, u_int, u_int = 0);
void nglListAddQuad(nglQuad *);

enum { NGLBM_OPAQUE = 0, NGLBM_BLEND = 1 };
#define NGL_RGBA32(r, g, b, a) (((int)((r)+1)>>1) | (((int)((g)+1)>>1)<<8) | (((int)((b)+1)>>1)<<16) | (((int)((a)+1)>>1)<<24))
#define FTOI(x) ((int)(x))

class IGOWidget
{
protected:
	bool display;
public:
	virtual ~IGOWidget();
	virtual void SetDisplay(bool = true);
	virtual void Update(float);
	virtual void Draw();
	virtual bool GetDisplay() const;
};

class PhotoWidget : public IGOWidget
{
	PanelQuad *borderPQ;
	int borderCenterX, borderCenterY, borderZ;
	nglTexture *photoTexture;
	nglQuad photoQuad, darkQuad;
	float darkFade;
	float fadeOutAlpha;
	float shownTimer;
	bool timed;
	int photoNum;
	TextString *pointText;
	int score, *scorePtr;
public:
	void Draw(void);
};

void PhotoWidget::Draw(void)
{	
	IGOWidget::Draw();

	if (!display)
		return;

	if (photoTexture)
	{
		borderPQ->SetCenterPos(borderCenterX, borderCenterY);
		borderPQ->SetZ(borderZ);
		borderPQ->SetFade(fadeOutAlpha);
		borderPQ->Draw(0);

		if (fadeOutAlpha < 1.0f)
		{
			nglSetQuadColor(&photoQuad, NGL_RGBA32(255, 255, 255, 255.0f*fadeOutAlpha));
			nglSetQuadBlend(&photoQuad, NGLBM_BLEND, 0);
		}
		else
		{
			nglSetQuadColor(&photoQuad, NGL_RGBA32(255, 255, 255, 255));
			nglSetQuadBlend(&photoQuad, NGLBM_OPAQUE, 0);
		}
		nglListAddQuad(&photoQuad);

		nglSetQuadColor(&darkQuad, NGL_RGBA32(64, 64, 64, FTOI(darkFade*255.0f)));
		nglListAddQuad(&darkQuad);

		pointText->color.set_alpha(255.0f*fadeOutAlpha);
		pointText->Draw();
	}
}
